using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OnPlayerCorruptAfflictionMultipleTimesOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/OnPlayerCorruptAfflictionMultipleTimes Omen Data")]
public class OnPlayerCorruptAfflictionMultipleTimesOmenData : OnPlayerCorruptAfflictionOmenData
{
	private Action<GameObject, int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(GameObject enemyTarget, int corruptAfflictionAmount)
		{
			if (IsMinimunCorruptAmount(corruptAfflictionAmount))
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				ActivateOmen(enemyTarget);
			}
		};
		ReferenceSingleton<SothisOmensHandler>.Instance.OnPlayerOrSentinelCorruptAfflictionMultipleTimesOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.OnPlayerOrSentinelCorruptAfflictionMultipleTimesOmenActions.Remove(omenAction);
	}
}
